apps.compose:
services:
  immich-kiosk:
    image: ghcr.io/damongolding/immich-kiosk:0.45.2
    restart: unless-stopped
    tty: true
    ports:
      - ${WEB_PORT:-3000}:3000
    environment:
      TZ: ${TZ:-UTC}
      KIOSK_IMMICH_URL: ${IMMICH_URL:?set IMMICH_URL, the address of Immich}
      KIOSK_IMMICH_API_KEY: ${IMMICH_API_KEY:?set IMMICH_API_KEY, an API key made in Immich}
      KIOSK_DURATION: ${DURATION:-60}
      KIOSK_SHOW_TIME: ${SHOW_TIME:-true}
      KIOSK_SHOW_DATE: ${SHOW_TIME:-true}
      KIOSK_TIME_FORMAT: "24"
      KIOSK_PASSWORD: ${KIOSK_PASSWORD:-}
    healthcheck:
      test: ["CMD", "/kiosk", "--healthcheck"]
      interval: 30s
      timeout: 5s
      retries: 3
      start_period: 10s

files.element.conf.template:
# Element and the Matrix server on one port. A template of the nginx image: ${…} are filled in
# from the environment at start, the lowercase $ variables are nginx's own.
server {
    listen       ${ELEMENT_WEB_PORT};
    listen  [::]:${ELEMENT_WEB_PORT};
    server_name  localhost;

    root   /usr/share/nginx/html;
    index  index.html;
    client_max_body_size 100M;

    # Element is told to use the server at this very address
    location = /config.json {
        default_type application/json;
        add_header Cache-Control "no-cache";
        return 200 '{"default_server_config":{"m.homeserver":{"base_url":"${APP_URL}","server_name":"${SERVER_NAME}"}},"disable_custom_urls":false,"disable_guests":true,"show_labs_settings":false,"room_directory":{"servers":["${SERVER_NAME}"]}}';
    }

    location ~ ^/(_matrix|_synapse/client|_continuwuity|\.well-known/matrix)/ {
        proxy_pass http://homeserver:8008;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_http_version 1.1;
        proxy_read_timeout 600s;
    }

    location = /index.html {
        add_header Cache-Control "no-cache";
    }
    location = /version {
        add_header Cache-Control "no-cache";
    }
    location /i18n/ {
        add_header Cache-Control "no-cache";
    }
}

apps.compose:
services:
  speedtest-tracker:
    image: linuxserver/speedtest-tracker:1.15.0
    restart: unless-stopped
    ports:
      - ${WEB_PORT:-8098}:80
    volumes:
      - ${APP_DATA:-.}/config:/config
    environment:
      PUID: ${PUID:-1000}
      PGID: ${PGID:-1000}
      TZ: ${TZ:-UTC}
      DISPLAY_TIMEZONE: ${TZ:-UTC}
      # Laravel takes a plain 32-character key as well as a "base64:" one
      APP_KEY: ${APP_KEY:?set APP_KEY, 32 letters and digits}
      APP_URL: ${APP_URL:-http://localhost:8098}
      DB_CONNECTION: sqlite
      ADMIN_EMAIL: ${ADMIN_EMAIL:?set ADMIN_EMAIL, the e-mail to sign in with}
      ADMIN_PASSWORD: ${ADMIN_PASSWORD:?set ADMIN_PASSWORD, the password to sign in with}
      SPEEDTEST_SCHEDULE: ${SPEEDTEST_SCHEDULE:-0 */6 * * *}
      PRUNE_RESULTS_OLDER_THAN: ${PRUNE_DAYS:-0}

services:
  vaultwarden:
    image: vaultwarden/server:1.37.4
    restart: unless-stopped
    ports:
      - ${WEB_PORT:-8080}:80
    volumes:
      - ${APP_DATA:-.}/data:/data
    environment:
      DOMAIN: ${APP_URL:-http://localhost}
      SIGNUPS_ALLOWED: ${SIGNUPS_ALLOWED:-true}
      ADMIN_TOKEN: ${ADMIN_TOKEN:-}
      TZ: ${TZ:-UTC}
